      fmt[0].height != BOARD_VELAPOKA_CAMERA_HEIGHT ||
      fmt[0].pixelformat != IMGSENSOR_PIX_FMT_SBGGR10P ||
      interval->numerator != 1 ||
      interval->denominator != BOARD_VELAPOKA_CAMERA_FPS)
    {
      return -ENOTSUP;
    }

  return OK;
}

