    mipi_csi_phy_ll_enable_shutdown_input(hal->host_dev, true);
    mipi_csi_phy_ll_enable_reset_output(hal->host_dev, true);
    mipi_csi_host_ll_enable_reset_output(hal->host_dev, true);
